        u_xlat18.xyz = vec3(u_xlat39) * u_xlat18.xyz + u_xlat3.xyz;
        u_xlat7.xy = u_xlat5.zw / _resolution.xy;
        u_xlat8.xyz = texture(inputImg, u_xlat7.xy).xyz;
        u_xlat39 = dot(u_xlat8.xzy, vec3(-0.5, -0.5, 1.0));
