    u_xlat2.xyz = u_xlat2.xyz * vec3(0.0288000014, 0.0288000014, 0.0288000014) + vec3(0.100000001, 0.100000001, 0.100000001);
    u_xlat2.xyz = min(u_xlat2.xyz, vec3(1.0, 1.0, 1.0));
