    u_xlat0.xyz = clamp(u_xlat0.xyz, 0.0, 1.0);
    u_xlat36 = texture(texture0, u_xlat1.zw).x;
    u_xlat36 = u_xlat36 * u_xlat1.y;
    u_xlat0.xyz = u_xlat0.xyz * _tint.xyz + vec3(u_xlat36);
    if(int(_use_inner_mask) != 0) {
